<?php
$title='Content Editor';require __DIR__.'/inc/header.php';$type=(string)get('type','articles');if(!in_array($type,['gadgets','jersey','fashion','articles','docs','pages'],true))$type='articles';$pdo=db();$id=(int)get('id',0);$creating=!$id;$form=null;if($id){$st=$pdo->prepare('SELECT * FROM content_posts WHERE id=? AND post_type=?');$st->execute([$id,$type]);$form=$st->fetch();if(!$form){flash('error','Content not found.');redirect('/admin/content.php?type='.$type);}}$form=$form?:['id'=>0,'title'=>'','slug'=>'','excerpt'=>'','content'=>'','status'=>'draft','visibility'=>'public','category_id'=>'','cover_image'=>'','seo_title'=>'','seo_description'=>'','seo_keywords'=>'','schema_type'=>'Article','featured'=>0];$cats=$pdo->query('SELECT id,name FROM categories WHERE status=1 ORDER BY type,name')->fetchAll();$st=$pdo->prepare("SELECT id,name FROM terms WHERE taxonomy='tag' AND post_type=? AND status=1 ORDER BY name");$st->execute([$type]);$tags=$st->fetchAll();$selectedTags=[];if($id){$st=$pdo->prepare('SELECT term_id FROM post_terms WHERE post_id=?');$st->execute([$id]);$selectedTags=array_map('intval',$st->fetchAll(PDO::FETCH_COLUMN));}$msg='';
if(is_post()){verify_csrf();$titleX=trim((string)post('title'));$slug=slugify((string)post('slug',$titleX));$excerpt=trim((string)post('excerpt'));$content=(string)post('content');$status=(string)post('status','draft');$visibility=(string)post('visibility','public');$cat=(int)post('category_id',0)?:null;$seoT=trim((string)post('seo_title'));$seoD=trim((string)post('seo_description'));$seoK=trim((string)post('seo_keywords'));$schema=(string)post('schema_type','Article');$featured=post('featured')?1:0;$cover=(string)post('existing_cover','');if(!empty($_FILES['cover_file']['name'])){try{$u=save_public_upload($_FILES['cover_file'],['jpg','jpeg','png','webp','gif','svg'],12000000,'content');$cover=$u['path'];}catch(Throwable $e){$msg=$e->getMessage();}}try{if($creating){$pdo->prepare('INSERT INTO content_posts(post_type,title,slug,excerpt,content,status,visibility,category_id,cover_image,seo_title,seo_description,seo_keywords,schema_type,featured,author_id,published_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$type,$titleX,$slug,$excerpt,$content,$status,$visibility,$cat,$cover,$seoT,$seoD,$seoK,$schema,$featured,user()['id']??null,$status==='publish'?date('Y-m-d H:i:s'):null]);$id=(int)$pdo->lastInsertId();}else{$pdo->prepare('UPDATE content_posts SET title=?,slug=?,excerpt=?,content=?,status=?,visibility=?,category_id=?,cover_image=?,seo_title=?,seo_description=?,seo_keywords=?,schema_type=?,featured=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND post_type=?')->execute([$titleX,$slug,$excerpt,$content,$status,$visibility,$cat,$cover,$seoT,$seoD,$seoK,$schema,$featured,$id,$type]);}$pdo->prepare('DELETE FROM post_terms WHERE post_id=?')->execute([$id]);foreach((array)post('tags',[]) as $tid)$pdo->prepare('INSERT OR IGNORE INTO post_terms(post_id,term_id) VALUES(?,?)')->execute([$id,(int)$tid]);flash('success',$creating?'Content created.':'Content updated.');redirect('/admin/content-edit.php?type='.$type.'&id='.$id);}catch(Throwable $e){$msg=$e->getMessage();}}
?>
<div class="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">EDITOR</div><h1 class="text-3xl font-black"><?=($creating?'New':'Edit')?> <?=e(post_type_label($type))?></h1></div><div class="flex gap-2"><a href="/admin/content.php?type=<?=$type?>" class="rounded-xl border px-4 py-3 font-bold">Back</a><?php if(!$creating):?><a href="<?=e(content_url($type,$form['slug']))?>" target="_blank" class="grad600 text-white px-4 py-3 rounded-xl font-black">View</a><?php endif;?></div></div>
