<form method="post" enctype="multipart/form-data" class="grid xl:grid-cols-[1fr_330px] gap-6"><?=csrf_input()?><div class="bg-white border rounded-2xl p-5 soft space-y-4"><input required name="title" value="<?=e($form['title'])?>" placeholder="Title" class="w-full"><input name="slug" value="<?=e($form['slug'])?>" placeholder="SEO slug" class="w-full"><textarea name="excerpt" placeholder="Short excerpt" class="w-full min-h-24"><?=e($form['excerpt'])?></textarea><div><div class="text-sm font-black mb-2">Professional Text + HTML Editor</div><?php require __DIR__.'/inc/rich_editor.php';rich_editor('content',(string)$form['content'],'contentEditorFull');?></div></div><div class="space-y-4"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">Publish</div><select name="status" class="w-full mb-2"><option value="draft" <?=$form['status']==='draft'?'selected':''?>>Draft</option><option value="publish" <?=$form['status']==='publish'?'selected':''?>>Publish</option><option value="private" <?=$form['status']==='private'?'selected':''?>>Private</option></select><select name="visibility" class="w-full mb-2"><option value="public" <?=$form['visibility']==='public'?'selected':''?>>Public</option><option value="members" <?=$form['visibility']==='members'?'selected':''?>>Members only</option></select><label class="flex items-center gap-2 text-sm"><input type="checkbox" name="featured" <?=$form['featured']?'checked':''?>> Featured</label></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">Category & Tags</div><select name="category_id" class="w-full mb-3"><option value="">No category</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$form['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><select name="tags[]" multiple class="w-full min-h-40"><?php foreach($tags as $t):?><option value="<?=$t['id']?>" <?=in_array((int)$t['id'],$selectedTags,true)?'selected':''?>><?=e($t['name'])?></option><?php endforeach;?></select></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">Cover Image</div><?php if($form['cover_image']):?><img src="<?=e($form['cover_image'])?>" class="w-full aspect-video object-cover rounded-xl mb-3"><?php endif;?><input type="hidden" name="existing_cover" value="<?=e($form['cover_image'])?>"><input type="file" name="cover_file" accept="image/*" class="w-full border rounded-xl p-3"></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black mb-3">SEO / Schema</div><input name="seo_title" value="<?=e($form['seo_title'])?>" placeholder="SEO title" class="w-full mb-2"><textarea name="seo_description" placeholder="Meta description" class="w-full min-h-20 mb-2"><?=e($form['seo_description'])?></textarea><input name="seo_keywords" value="<?=e($form['seo_keywords'])?>" placeholder="Meta keywords" class="w-full mb-2"><select name="schema_type" class="w-full"><option <?=($form['schema_type']==='Article'?'selected':'')?>>Article</option><option <?=($form['schema_type']==='Product'?'selected':'')?>>Product</option><option <?=($form['schema_type']==='WebPage'?'selected':'')?>>WebPage</option></select></div><button class="grad600 text-white w-full rounded-xl py-3 font-black">Save Changes</button></div></form>
